CREATE FUNCTION public.business_contact_public_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.can_manage_account_connections(NEW.workspace_id) THEN RAISE EXCEPTION 'Active non-contractor business manager required'; END IF;
 IF TG_OP='UPDATE' THEN
 IF NEW.business_contact_email IS DISTINCT FROM OLD.business_contact_email THEN NEW.contact_email_public:=false; END IF;
 IF NEW.business_contact_phone IS DISTINCT FROM OLD.business_contact_phone THEN NEW.contact_phone_public:=false; END IF;
 IF (NEW.contact_email_public AND NOT OLD.contact_email_public OR NEW.contact_phone_public AND NOT OLD.contact_phone_public) AND coalesce(current_setting('app.business_identity_confirmed',true),'')<>'true' THEN RAISE EXCEPTION 'Explicit business contact confirmation required'; END IF;
 ELSE IF (NEW.contact_email_public OR NEW.contact_phone_public) AND coalesce(current_setting('app.business_identity_confirmed',true),'')<>'true' THEN RAISE EXCEPTION 'Explicit business contact confirmation required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER business_contact_public_guard BEFORE INSERT OR UPDATE ON public.provider_network_profiles FOR EACH ROW EXECUTE FUNCTION public.business_contact_public_guard();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='save_shared_business_identity'; definition:=replace(definition,'PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;',$s$PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE; PERFORM set_config('app.business_identity_confirmed','true',true);$s$); EXECUTE definition; END $$;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='patient_request_snapshot'; definition:=replace(definition,$s$'events',jsonb_build_array$s$,$s$'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('action',CASE WHEN d.event_type IN ('scheduled','dispatch_scheduled') THEN 'scheduled' ELSE 'driver_assigned' END,'at',coalesce(d.event_time,d.created_at)) ORDER BY coalesce(d.event_time,d.created_at)),'[]'::jsonb) FROM public.trip_dispatch_events d WHERE d.trip_id=t.id AND (d.event_type IN ('scheduled','dispatch_scheduled') OR (d.event_type='driver_assigned' AND t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed'))))||jsonb_build_array$s$); EXECUTE definition; END $$;
COMMENT ON COLUMN public.provider_network_profiles.contact_email_public IS 'Exact contact consent: changing email withdraws this flag; confirm the new saved email in a subsequent identity review.';
COMMENT ON COLUMN public.provider_network_profiles.contact_phone_public IS 'Exact contact consent: changing phone withdraws this flag; confirm the new saved phone in a subsequent identity review.';